record.field:
for rec in records:
    vals = {}

    if rec.indoor_gross_area:
        vals['indoor_gross_area'] = -(-rec.indoor_gross_area // 1)

    if rec.terrace_gross_area:
        vals['terrace_gross_area'] = -(-rec.terrace_gross_area // 1)

    if rec.outdoor_gross_area:
        vals['outdoor_gross_area'] = -(-rec.outdoor_gross_area // 1)

    if vals:
        rec.write(vals)
